messages.content:
Game edukasi sejarah Nusantara dengan mekanik ambil peninggalan sesuai kategori target (Hindu-Buddha vs Islam), tema Retro Pixel, kesulitan Normal. Asumsi: item Majapahit (Negarakertagama, Gajah Mada) sengaja masuk kategori Hindu-Buddha untuk meluruskan miskonsepsi.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "nusantara-legacy-run", title: "Nusantara Legacy Run", seed: "nusantara-01",
  theme: { preset: "retro-pixel" },

  learning: {
    subject: "Sejarah Indonesia",
    concept: "Perbandingan kerajaan Hindu-Buddha dan Islam di Nusantara",
    objectives: [
      "Mengelompokkan peninggalan dan tokoh berdasarkan corak kerajaan Hindu-Buddha atau Islam"
    ],
    misconceptions: [
      "Majapahit dianggap kerajaan Islam padahal bercorak Hindu-Buddha"
    ],
    mode: "category",
    categories: [
      { id: "hindu-buddha", label: "Hindu-Buddha", color: "#E8A33D" },
      { id: "islam",        label: "Islam",        color: "#3FA34D" }
    ],
    items: [
      { id: "borobudur",   label: "Candi Borobudur",     category: "hindu-buddha", explain: "Candi Buddha peninggalan Dinasti Syailendra." },
      { id: "prambanan",   label: "Candi Prambanan",     category: "hindu-buddha", explain: "Candi Hindu Siwa peninggalan Wangsa Sanjaya." },
      { id: "yupa",        label: "Prasasti Yupa",       category: "hindu-buddha", explain: "Prasasti tertua Kutai, bercorak Hindu." },
      { id: "negarakertagama", label: "Negarakertagama", category: "hindu-buddha", explain: "Kitab pujangga Mpu Prapanca dari Majapahit yang Hindu-Buddha." },
      { id: "gajah-mada",  label: "Patih Gajah Mada",    category: "hindu-buddha", explain: "Mahapatih Majapahit, kerajaan bercorak Hindu-Buddha." },
      { id: "masjid-demak", label: "Masjid Agung Demak", category: "islam",        explain: "Masjid peninggalan Kesultanan Demak, kerajaan Islam." },
      { id: "masjid-kudus", label: "Masjid Kudus",       category: "islam",        explain: "Masjid bercorak Islam dengan menara bata khas." },
      { id: "samudera-pasai", label: "Samudera Pasai",   category: "islam",        explain: "Kesultanan Islam pertama di Nusantara, di Aceh." },
      { id: "aceh",        label: "Kesultanan Aceh",     category: "islam",        explain: "Kesultanan Islam maritim yang berpusat di Aceh." },
      { id: "raden-patah", label: "Raden Patah",         category: "islam",        explain: "Pendiri Kesultanan Demak, kerajaan Islam di Jawa." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",     w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "semak",    w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
